-- Nouvelles categories necessaires pour l'import OpenStreetMap (station-
-- service et marche n'existaient pas, et etre range dans "Point
-- geographique" par defaut aurait ete peu pertinent).
INSERT INTO public.categories (nom, slug, icone, ordre)
VALUES
  ('Station-service', 'station-service', '⛽', 90),
  ('Marché', 'marche', '🛒', 91)
ON CONFLICT (slug) DO NOTHING;

