  -- Dedoublonnage grossier : meme nom (insensible casse) a moins de 100m
  -- d'un lieu deja actif.
  SELECT 1 FROM public.places p
  WHERE p.actif = true
    AND lower(p.nom) = lower(v.nom)
    AND ST_DWithin(p.location, ST_SetSRID(ST_MakePoint(v.longitude, v.latitude), 4326)::geography, 100)
);
